const own=(object,key)=>Object.prototype.hasOwnProperty.call(object,key);
function glyph(source){
 if(!own(sources,source))throw new RangeError('Unmapped approved icon: '+source);
 return sources[source].replace('<svg ','<svg class="glyph approved-talent-glyph" aria-hidden="true" focusable="false" data-approved-source="'+source+'" data-approved-sha256="'+APPROVED_TALENT_ICON_SOURCES[source]+'" ');
}
export function approvedTalentIconRef(node){
 const id=typeof node==='string'?node:node?.id;
 if(!own(APPROVED_TALENT_NODE_MAP,id))throw new RangeError('Unmapped talent node: '+id);
 const row=APPROVED_TALENT_NODE_MAP[id];
 if(typeof node==='object'&&(node.kind!==row.kind||node.sector!==row.sector||(node.effect??null)!==row.effect))throw new Error('Talent schema changed: '+id);
 return row.source;
}
export function approvedTalentNodeGlyph(node){return glyph(approvedTalentIconRef(node));}
export function approvedTalentSectorGlyph(index){
 if(!Number.isInteger(index)||index<0||index>=APPROVED_TALENT_SECTORS.length)throw new RangeError('Unknown talent sector: '+index);
 return glyph(APPROVED_TALENT_SECTORS[index].approvedSource);
}
export function approvedSkillGlyph(id){return glyph('habilidades/'+id);}
export function approvedSkillSlotGlyph(id=null){return id===null?glyph('icones/empty'):approvedSkillGlyph(id);}
